from pwn import *

def test_cipher():
    server = "crypto.chal.csaw.io"
    port = 4512

    inputs = ["A" * i for i in range(1, 50)]  # Progressive lengths of input
    recorded_ciphertexts = {}

    for i, inp in enumerate(inputs):
        try:
            io = remote(server, port)
            io.sendlineafter("> ", inp.encode())
            ciphertext = io.recvline().decode().strip()
            recorded_ciphertexts[inp] = ciphertext
            io.close()
        except Exception as e:
            print(f"Error for input {inp}: {e}")

    # Save the recorded ciphertexts for examination
    with open("/home/ctfplayer/ciphertext_results.txt", "w") as f:
        for ptext, ctext in recorded_ciphertexts.items():
            f.write(f"Input: {ptext} -> Ciphertext: {ctext}\n")

if __name__ == "__main__":
    test_cipher()

from binascii import unhexlify

def xor_bytes(b1, b2):
    """Perform XOR between two byte objects of the same length."""
    return bytes(a ^ b for a, b in zip(b1, b2))

# Given ciphertexts in hex
ciphertexts = {
    'A': "0ebd93163934e33432bbb4157f3c72d90546181c8c5771c563d905fe9fa2fa8229b21c",
    'AA': "9724733cd0770ee9a0441274c4d22484e91166c1eb134a96f67ad0fbdf3f553ce0582c43",
    'AAA': "3acf25e075d142e05b0be07d68213133694eb1cc98cf6672bfd24414ba20cf8cc44832945f",
    'AAAAA': "08c83e64ebc7d9a415b9e46b71e16567a10a443dd122f5fde0496ebb3019269701c617d1dce649"
}

# Convert hex to bytes
cipher_as_bytes = {k: unhexlify(v) for k, v in ciphertexts.items()}

# Perform XOR between consecutive ciphertexts
xor_results = {
    'A_vs_AA': xor_bytes(cipher_as_bytes['A'], cipher_as_bytes['AA'][:len(cipher_as_bytes['A'])]),
    'AA_vs_AAA': xor_bytes(cipher_as_bytes['AA'], cipher_as_bytes['AAA'][:len(cipher_as_bytes['AA'])]),
    'AAA_vs_AAAAA': xor_bytes(cipher_as_bytes['AAA'], cipher_as_bytes['AAAAA'][:len(cipher_as_bytes['AAA'])])
}

# Write XOR results to a file
with open('xor_analysis.txt', 'w') as f:
    for comparison, result in xor_results.items():
        f.write(f"{comparison}: {result.hex()}\n")

